# Hindi / Gujarati text for Political Science Ch 3 lesson, sections 3-5.
TEXT_B = {
 "s3.thm.title": ("सांप्रदायिकता और धर्मनिरपेक्ष शासन", "કોમવાદ અને બિનસાંપ્રદાયિક રાજ્ય"),
 "s3.thm.body": (
  "धार्मिक भिन्नताएँ अक्सर राजनीति में अभिव्यक्त होती हैं। क्या यह हमेशा ग़लत है? ज़रूरी नहीं:\n"
  "- **गांधीजी** कहा करते थे कि धर्म को कभी भी राजनीति से अलग नहीं किया जा सकता। धर्म से उनका मतलब किसी ख़ास धर्म से नहीं, बल्कि उन **नैतिक मूल्यों** से था जो सभी धर्मों से जुड़े हैं। उनका मानना था कि राजनीति धर्म द्वारा स्थापित मूल्यों से निर्देशित होनी चाहिए।\n"
  "- मानवाधिकार समूहों का कहना है कि हमारे देश में सांप्रदायिक दंगों में मरने वाले अधिकतर लोग **अल्पसंख्यक समुदायों** के हैं, और उन्होंने सरकार से उनकी रक्षा के विशेष क़दम उठाने की माँग की है।\n"
  "- महिला आंदोलन का कहना है कि सभी धर्मों के **पारिवारिक क़ानून** महिलाओं से भेदभाव करते हैं, और उन्होंने इन्हें अधिक न्यायपूर्ण बनाने की माँग की है।\n\n"
  "इन सबमें धर्म और राजनीति का संबंध है, और ये ग़लत नहीं हैं। हर व्यक्ति को एक धार्मिक समुदाय के सदस्य के रूप में अपनी ज़रूरतें, हित और माँगें राजनीति में उठाने का अधिकार होना चाहिए। राजनीतिक सत्ता में बैठे लोगों को भेदभाव और उत्पीड़न रोकने के लिए **धर्म के कामकाज पर नियंत्रण** रखने में सक्षम होना चाहिए। ये काम तब तक ठीक हैं जब तक वे हर धर्म के साथ **समान** बर्ताव करते हैं।\n\n"
  "**सांप्रदायिकता:** समस्या तब शुरू होती है जब धर्म को **राष्ट्र का आधार** मान लिया जाता है। समस्या और विकराल तब होती है जब राजनीति में धर्म की अभिव्यक्ति एक समुदाय की विशिष्टता के दावे और पक्षपोषण का रूप लेने लगती है, जब एक धर्म के अनुयायियों को दूसरे धर्म के ख़िलाफ़ मोर्चा बनाया जाता है, जब एक धर्म के विश्वासों को दूसरों से श्रेष्ठ बताया जाता है, जब एक धार्मिक समूह की माँगों को दूसरे के विरोध में खड़ा किया जाता है, और जब **राज्य की सत्ता** का इस्तेमाल किसी एक धर्म का वर्चस्व स्थापित करने के लिए होता है। राजनीति से धर्म को इस तरह जोड़ना ही **सांप्रदायिक राजनीति** है।\n"
  "- सांप्रदायिक राजनीति इस सोच पर आधारित है कि **धर्म ही सामाजिक समुदाय का निर्माण करता है**। इसके अनुसार एक धर्म के अनुयायी एक समुदाय के होते हैं, उनके मौलिक हित एक जैसे होते हैं, और अलग-अलग धर्मों के लोग एक सामाजिक समुदाय के नहीं हो सकते।\n"
  "- यह सोच ग़लत है: एक धर्म के लोगों के हित और आकांक्षाएँ हर मामले में एक-सी नहीं होतीं। हर व्यक्ति की कई और भूमिकाएँ, हैसियत और पहचान होती है। हर समुदाय के अंदर कई तरह की आवाज़ें होती हैं।\n\n"
  "**राजनीति में सांप्रदायिकता के रूप:**\n"
  "1. **रोज़मर्रा के विश्वास:** इनमें धार्मिक पूर्वाग्रह, धार्मिक समुदायों के बारे में बनी-बनाई धारणाएँ और अपने धर्म को दूसरों से श्रेष्ठ मानना शामिल है। यह इतना आम है कि हम अक्सर इस पर ध्यान नहीं देते।\n"
  "2. **राजनीतिक प्रभुत्व की चाह:** सांप्रदायिक सोच अक्सर अपने धार्मिक समुदाय का राजनीतिक प्रभुत्व स्थापित करने की फ़िराक़ में रहती है। बहुसंख्यक समुदाय के लिए यह **बहुसंख्यकवादी प्रभुत्व** का रूप लेती है; अल्पसंख्यक समुदाय के लिए यह **अलग राजनीतिक इकाई** बनाने की इच्छा का रूप ले सकती है।\n"
  "3. **धार्मिक आधार पर राजनीतिक गोलबंदी:** इसमें धर्म के पवित्र प्रतीकों, धर्मगुरुओं, भावनात्मक अपील और साफ़-साफ़ डर का इस्तेमाल करके एक धर्म के अनुयायियों को राजनीति में एकजुट किया जाता है। चुनावी राजनीति में इसका अर्थ अक्सर एक धर्म के मतदाताओं की भावनाओं या हितों की बात ख़ास तौर पर उठाना होता है।\n"
  "4. **सांप्रदायिक हिंसा, दंगे और नरसंहार:** कभी-कभी सांप्रदायिकता अपना सबसे घिनौना रूप लेती है। **विभाजन** के समय **भारत और पाकिस्तान** ने भयानक सांप्रदायिक दंगे झेले, और आज़ादी के बाद भी बड़े पैमाने पर सांप्रदायिक हिंसा हुई है।\n\n"
  "**धर्मनिरपेक्ष शासन:** सांप्रदायिकता हमारे देश के लोकतंत्र के लिए एक बड़ी चुनौती रही है और आज भी है। हमारे संविधान निर्माताओं ने **धर्मनिरपेक्ष शासन** का मॉडल चुना:\n"
  "- भारतीय राज्य का **कोई आधिकारिक धर्म नहीं** है। श्रीलंका में **बौद्ध धर्म**, पाकिस्तान में **इस्लाम** और इंग्लैंड में **ईसाई धर्म** को जो विशेष दर्जा मिला है, उसके विपरीत हमारा संविधान किसी धर्म को विशेष दर्जा नहीं देता।\n"
  "- संविधान सभी नागरिकों और समुदायों को **किसी भी धर्म का पालन करने, प्रचार और अभ्यास करने** की आज़ादी देता है, या किसी धर्म को न मानने की भी।\n"
  "- संविधान धर्म के आधार पर किए जाने वाले किसी तरह के **भेदभाव को अवैधानिक** घोषित करता है।\n"
  "- साथ ही, संविधान धार्मिक समुदायों में **समानता** सुनिश्चित करने के लिए शासन को **धार्मिक मामलों में दख़ल** देने का अधिकार देता है। जैसे, यह **छुआछूत** पर रोक लगाता है।\n\n"
  "धर्मनिरपेक्षता कुछ पार्टियों या व्यक्तियों की एक विचारधारा भर नहीं, बल्कि हमारे देश की **बुनियाद** है। सांप्रदायिकता से रोज़मर्रा के विश्वासों में भी और राजनीति में धर्म-आधारित गोलबंदी में भी लड़ना होगा।",
  "ધાર્મિક ભિન્નતાઓ ઘણી વાર રાજકારણમાં વ્યક્ત થાય છે. શું તે હંમેશાં ખોટું છે? જરૂરી નથી:\n"
  "- **ગાંધીજી** કહેતા કે ધર્મને રાજકારણથી ક્યારેય અલગ કરી શકાય નહિ. ધર્મથી તેમનો અર્થ કોઈ ખાસ ધર્મ નહિ, પણ બધા ધર્મોમાં રહેલાં **નૈતિક મૂલ્યો** હતો. તેઓ માનતા કે રાજકારણ ધર્મમાંથી મળતી નીતિમત્તાથી માર્ગદર્શિત થવું જોઈએ.\n"
  "- માનવ અધિકાર જૂથોનું કહેવું છે કે આપણા દેશમાં કોમી રમખાણોના મોટા ભાગના ભોગ **ધાર્મિક લઘુમતીઓ**ના લોકો છે, અને તેમણે સરકાર પાસે તેમના રક્ષણ માટે ખાસ પગલાં લેવાની માગણી કરી છે.\n"
  "- સ્ત્રી આંદોલનનું કહેવું છે કે બધા ધર્મોના **કૌટુંબિક કાયદા** સ્ત્રીઓ સાથે ભેદભાવ કરે છે, અને તેમણે તેને વધુ ન્યાયી બનાવવાની માગણી કરી છે.\n\n"
  "આ બધામાં ધર્મ અને રાજકારણનો સંબંધ છે, અને તે ખોટું નથી. દરેક વ્યક્તિ ધાર્મિક સમુદાયના સભ્ય તરીકે પોતાની જરૂરિયાતો, હિતો અને માગણીઓ રાજકારણમાં વ્યક્ત કરી શકે. રાજકીય સત્તા ધરાવનારાઓ ભેદભાવ અને દમન રોકવા **ધર્મના આચરણનું નિયમન** કરી શકે. આ કાર્યો ત્યાં સુધી યોગ્ય છે જ્યાં સુધી તે દરેક ધર્મ સાથે **સમાન** વર્તન કરે.\n\n"
  "**કોમવાદ:** સમસ્યા ત્યારે શરૂ થાય છે જ્યારે ધર્મને **રાષ્ટ્રનો આધાર** માનવામાં આવે. સમસ્યા વધુ ગંભીર ત્યારે બને છે જ્યારે રાજકારણમાં ધર્મ અલગતાવાદી અને પક્ષપાતી રીતે વ્યક્ત થાય, જ્યારે એક ધર્મ અને તેના અનુયાયીઓને બીજાની સામે મૂકવામાં આવે, જ્યારે એક ધર્મની માન્યતાઓને બીજા કરતાં ચડિયાતી બતાવાય, જ્યારે એક ધાર્મિક જૂથની માગણીઓ બીજાના વિરોધમાં ઘડાય, અને જ્યારે **રાજ્યસત્તા**નો ઉપયોગ એક ધાર્મિક જૂથનું વર્ચસ્વ સ્થાપવા થાય. રાજકારણમાં ધર્મનો આવો ઉપયોગ **કોમવાદી રાજકારણ** છે.\n"
  "- કોમવાદી રાજકારણ એ વિચાર પર આધારિત છે કે **ધર્મ જ સામાજિક સમુદાયનો મુખ્ય આધાર છે**. તે માને છે કે એક ધર્મના અનુયાયીઓ એક સમુદાયના છે, તેમનાં મૂળભૂત હિતો સરખાં છે, અને જુદા ધર્મના લોકો એક સામાજિક સમુદાયના હોઈ શકે નહિ.\n"
  "- આ માન્યતા ખોટી છે: એક ધર્મના લોકોનાં હિતો અને આકાંક્ષાઓ દરેક સંદર્ભમાં સરખાં હોતાં નથી. દરેક વ્યક્તિની બીજી અનેક ભૂમિકાઓ, સ્થાન અને ઓળખ હોય છે. દરેક સમુદાયમાં અનેક અવાજો હોય છે.\n\n"
  "**રાજકારણમાં કોમવાદનાં સ્વરૂપો:**\n"
  "1. **રોજિંદી માન્યતાઓ:** તેમાં ધાર્મિક પૂર્વગ્રહો, ધાર્મિક સમુદાયો વિશેની રૂઢ માન્યતાઓ અને પોતાના ધર્મને બીજા કરતાં ચડિયાતો માનવાનો સમાવેશ થાય છે. તે એટલું સામાન્ય છે કે આપણે ઘણી વાર તેની નોંધ લેતા નથી.\n"
  "2. **રાજકીય વર્ચસ્વની ઇચ્છા:** કોમવાદી માનસ ઘણી વાર પોતાના ધાર્મિક સમુદાયનું રાજકીય વર્ચસ્વ ઇચ્છે છે. બહુમતી સમુદાય માટે તે **બહુમતીવાદી વર્ચસ્વ**નું સ્વરૂપ લે છે; લઘુમતી સમુદાય માટે તે **અલગ રાજકીય એકમ** રચવાની ઇચ્છાનું સ્વરૂપ લઈ શકે છે.\n"
  "3. **ધાર્મિક ધોરણે રાજકીય એકત્રીકરણ:** તેમાં પવિત્ર પ્રતીકો, ધર્મગુરુઓ, લાગણીશીલ અપીલ અને સીધા ભયનો ઉપયોગ કરી એક ધર્મના અનુયાયીઓને રાજકારણમાં એક કરાય છે. ચૂંટણી રાજકારણમાં તેનો અર્થ ઘણી વાર એક ધર્મના મતદારોનાં હિતો કે લાગણીઓને ખાસ અપીલ કરવી હોય છે.\n"
  "4. **કોમી હિંસા, રમખાણો અને હત્યાકાંડ:** ક્યારેક કોમવાદ સૌથી ભયાનક સ્વરૂપ લે છે. **ભાગલા** વખતે **ભારત અને પાકિસ્તાને** ભયંકર કોમી રમખાણો સહન કર્યાં, અને આઝાદી પછી પણ મોટા પાયે કોમી હિંસા થઈ છે.\n\n"
  "**બિનસાંપ્રદાયિક રાજ્ય:** કોમવાદ આપણા દેશની લોકશાહી માટે મોટો પડકાર હતો અને હજી છે. આપણા બંધારણ ઘડવૈયાઓએ **બિનસાંપ્રદાયિક રાજ્ય**નું મૉડલ પસંદ કર્યું:\n"
  "- ભારતીય રાજ્યનો **કોઈ સત્તાવાર ધર્મ નથી**. શ્રીલંકામાં **બૌદ્ધ ધર્મ**, પાકિસ્તાનમાં **ઇસ્લામ** અને ઇંગ્લૅન્ડમાં **ખ્રિસ્તી ધર્મ**ને મળેલા વિશેષ દરજ્જાથી વિપરીત, આપણું બંધારણ કોઈ ધર્મને વિશેષ દરજ્જો આપતું નથી.\n"
  "- બંધારણ બધી વ્યક્તિઓ અને સમુદાયોને **કોઈ પણ ધર્મ પાળવાની, આચરવાની અને પ્રચાર કરવાની** સ્વતંત્રતા આપે છે, અથવા કોઈ ધર્મ ન પાળવાની પણ.\n"
  "- બંધારણ ધર્મના આધારે થતા **ભેદભાવ પર પ્રતિબંધ** મૂકે છે.\n"
  "- સાથે જ, બંધારણ ધાર્મિક સમુદાયોમાં **સમાનતા** સુનિશ્ચિત કરવા રાજ્યને **ધાર્મિક બાબતોમાં દખલ** કરવાની છૂટ આપે છે. ઉદાહરણ તરીકે, તે **અસ્પૃશ્યતા** પર પ્રતિબંધ મૂકે છે.\n\n"
  "બિનસાંપ્રદાયિકતા કેટલાક પક્ષો કે વ્યક્તિઓની વિચારધારા માત્ર નથી; તે આપણા દેશનો **પાયો** છે. કોમવાદ સામે રોજિંદી માન્યતાઓમાં અને રાજકારણમાં ધર્મ આધારિત એકત્રીકરણમાં લડવું પડશે."),
 "s3.table.title": ("सांप्रदायिक राजनीति के रूप", "કોમવાદી રાજકારણનાં સ્વરૂપો"),
 "s3.table.body": (
  "| सांप्रदायिक राजनीति का रूप | उदाहरण |\n|---|---|\n| **रोज़मर्रा के विश्वास**: धार्मिक पूर्वाग्रह, बनी-बनाई धारणाएँ और अपने धर्म को श्रेष्ठ मानना | यह सोचना कि दूसरे धर्म के सब लोग एक जैसे या हीन हैं |\n"
  "| **राजनीतिक प्रभुत्व की चाह**: बहुसंख्यक का बहुसंख्यकवादी प्रभुत्व, या अल्पसंख्यक की अलग राजनीतिक इकाई | माँग करना कि राज्य एक धर्म का पालन करे; धर्म के आधार पर अलग राज्य की माँग |\n"
  "| **धार्मिक आधार पर राजनीतिक गोलबंदी**: पवित्र प्रतीक, धर्मगुरु, भावनात्मक अपील और डर | वोट पाने के लिए धार्मिक नारों और दूसरे समुदाय के डर का इस्तेमाल |\n"
  "| **सांप्रदायिक हिंसा, दंगे और नरसंहार** | 1947 में विभाजन के समय के दंगे |",
  "| કોમવાદી રાજકારણનું સ્વરૂપ | ઉદાહરણ |\n|---|---|\n| **રોજિંદી માન્યતાઓ**: ધાર્મિક પૂર્વગ્રહો, રૂઢ માન્યતાઓ અને પોતાના ધર્મને ચડિયાતો માનવો | એવું માનવું કે બીજા ધર્મના બધા લોકો સરખા કે ઊતરતા છે |\n"
  "| **રાજકીય વર્ચસ્વની ઇચ્છા**: બહુમતીનું બહુમતીવાદી વર્ચસ્વ, કે લઘુમતીનું અલગ રાજકીય એકમ | રાજ્ય એક ધર્મ પાળે તેવી માગણી; ધર્મના આધારે અલગ રાજ્યની માગણી |\n"
  "| **ધાર્મિક ધોરણે રાજકીય એકત્રીકરણ**: પવિત્ર પ્રતીકો, ધર્મગુરુઓ, લાગણીશીલ અપીલ અને ભય | મત મેળવવા ધાર્મિક સૂત્રો અને બીજા સમુદાયના ભયનો ઉપયોગ |\n"
  "| **કોમી હિંસા, રમખાણો અને હત્યાકાંડ** | 1947માં ભાગલા વખતનાં રમખાણો |"),
 "s4.thm.title": ("जातिगत असमानताएँ, राजनीति में जाति और जाति के अंदर राजनीति", "જ્ઞાતિગત અસમાનતાઓ, રાજકારણમાં જ્ઞાતિ અને જ્ઞાતિમાં રાજકારણ"),
 "s4.thm.body": (
  "**जातिगत असमानताएँ:** लिंग और धर्म के विपरीत, जाति पर आधारित विभाजन सिर्फ़ भारत में है। सभी समाजों में कुछ सामाजिक असमानता और श्रम विभाजन होता है, पर अधिकतर समाजों में पेशे एक पीढ़ी से दूसरी पीढ़ी में नहीं जाते। जाति व्यवस्था इसका अतिवादी रूप है: यह **वंशानुगत पेशागत विभाजन** पर आधारित है जिसे रीति-रिवाजों की मान्यता प्राप्त है।\n"
  "- एक जाति के सदस्य एक सामाजिक समुदाय बनाते थे जो एक या मिलते-जुलते पेशे करते थे, अपनी जाति में ही शादी करते थे और दूसरी जाति के लोगों के साथ खान-पान नहीं करते थे।\n"
  "- जाति व्यवस्था 'अछूत' समूहों के बहिष्कार और उनसे भेदभाव पर आधारित थी, जिन्हें **छुआछूत** की अमानवीय प्रथा झेलनी पड़ती थी।\n"
  "- **जोतिबा फुले, गांधीजी, बी.आर. आंबेडकर और पेरियार रामास्वामी नायकर** जैसे राजनेताओं और समाज सुधारकों ने ऐसे समाज के लिए काम किया जिसमें जातिगत असमानताएँ न हों।\n\n"
  "**आधुनिक भारत में बदलाव:** कुछ हद तक इन लोगों के प्रयासों से और कुछ अन्य सामाजिक-आर्थिक बदलावों से जाति और जाति व्यवस्था में भारी बदलाव आए हैं। **आर्थिक विकास, बड़े पैमाने पर शहरीकरण, साक्षरता और शिक्षा के विकास, पेशा चुनने की आज़ादी** और गाँवों में ज़मींदारों की स्थिति कमज़ोर होने से जाति व्यवस्था के पुराने स्वरूप टूट रहे हैं। शहरों में अब इस बात का ज़्यादा महत्त्व नहीं है कि सड़क पर हमारे साथ कौन चल रहा है या रेस्तराँ में बगल की मेज़ पर कौन खा रहा है। **संविधान ने जाति पर आधारित किसी भी भेदभाव का निषेध** किया और जाति व्यवस्था से पैदा हुए अन्याय को समाप्त करने वाली नीतियों का आधार तैयार किया।\n\n"
  "**पर जाति ख़त्म नहीं हुई:**\n"
  "- अब भी अधिकतर लोग **अपनी जाति या क़बीले में ही शादी** करते हैं।\n"
  "- संवैधानिक प्रावधान के बावजूद **छुआछूत** की प्रथा पूरी तरह ख़त्म नहीं हुई है।\n"
  "- सदियों से जिन जातियों को लाभ मिला और जिनसे वंचित रखा गया, उसका असर आज भी दिखता है। जिन जातियों के पास पहले से शिक्षा की पहुँच थी, उन्होंने आधुनिक शिक्षा में भी अच्छा किया; जिन्हें शिक्षा से वंचित रखा गया, वे पिछड़ गईं। इसीलिए शहरी मध्यवर्ग में **'अगड़ी' जातियों** का अनुपात बहुत ज़्यादा है। जाति अब भी **आर्थिक हैसियत** से बहुत गहरे जुड़ी है।\n\n"
  "**राजनीति में जाति:** राजनीति में जाति कई रूपों में दिखती है:\n"
  "- चुनाव के लिए उम्मीदवार तय करते समय पार्टियाँ **मतदाताओं की जातियों का हिसाब** ध्यान में रखती हैं और अलग-अलग जातियों से उम्मीदवार उतारती हैं ताकि जीतने के लिए ज़रूरी समर्थन मिल सके।\n"
  "- राजनीतिक पार्टियाँ और उम्मीदवार समर्थन पाने के लिए **जातिगत भावनाओं** को उकसाते हैं। कुछ पार्टियों को कुछ जातियों के मददगार और प्रतिनिधि के रूप में देखा जाता है।\n"
  "- **सार्वभौम वयस्क मताधिकार** और **एक व्यक्ति-एक वोट** की व्यवस्था ने राजनीतिक दलों को विवश किया कि वे राजनीतिक समर्थन पाने और लोगों को गोलबंद करने के लिए सक्रिय हों। इससे उन जातियों के लोगों में नई चेतना पैदा हुई जिन्हें अब तक छोटा और नीच माना जाता था।\n\n"
  "**केवल जाति से चुनाव तय नहीं होते:**\n"
  "- देश के **किसी भी एक संसदीय चुनाव क्षेत्र** में किसी एक जाति का स्पष्ट बहुमत नहीं है। इसलिए हर उम्मीदवार और पार्टी को एक से अधिक जातियों और समुदायों का भरोसा जीतना पड़ता है।\n"
  "- **कोई भी पार्टी किसी एक जाति या समुदाय के सभी लोगों का वोट नहीं पा सकती।** जब लोग किसी जाति को किसी पार्टी का 'वोट बैंक' कहते हैं, तो इसका मतलब होता है कि उस जाति के ज़्यादातर लोग उसी पार्टी को वोट देते हैं।\n"
  "- अनेक पार्टियाँ **एक ही जाति** से उम्मीदवार उतार सकती हैं, इसलिए कुछ मतदाताओं के पास अपनी जाति के एक से अधिक उम्मीदवार होते हैं, तो कई के पास एक भी नहीं।\n"
  "- हमारे देश में सत्तारूढ़ दल और वर्तमान सांसदों-विधायकों को अक्सर **हार का सामना** करना पड़ता है। अगर जातियों और समुदायों की राजनीतिक पसंद एक ही होती, तो ऐसा संभव नहीं होता।\n"
  "- मतदाताओं का लगाव राजनीतिक दलों से भी होता है, जो अक्सर जाति के लगाव से ज़्यादा मज़बूत होता है। एक जाति या समुदाय के लोगों के हित उनकी **आर्थिक स्थिति** के अनुसार अलग-अलग होते हैं। एक जाति के अमीर और ग़रीब, या औरत और मर्द अक्सर अलग-अलग वोट देते हैं। **सरकार के कामकाज** के बारे में लोगों की राय और **नेताओं की लोकप्रियता** का भी चुनाव पर निर्णायक असर होता है।\n\n"
  "**जाति के अंदर राजनीति:** राजनीति जातिग्रस्त नहीं होती, बल्कि जाति ही राजनीतिग्रस्त हो जाती है:\n"
  "- हर जाति ख़ुद को बड़ा बनाने के लिए अपने अंदर उन पड़ोसी जातियों या उप-जातियों को भी शामिल करने की कोशिश करती है जिन्हें पहले बाहर रखा गया था।\n"
  "- अलग-अलग जातियों को दूसरी जातियों या समुदायों के साथ **गठबंधन** बनाना पड़ता है, और इस तरह उनके बीच संवाद और मोल-तोल होता है।\n"
  "- राजनीति में **'पिछड़ा' और 'अगड़ा'** जैसे नए जातिगत समूह सामने आए हैं।\n\n"
  "**प्रभाव:** जातिगत राजनीति से **दलितों और पिछड़ी जातियों** को सत्ता तक बेहतर पहुँच और फ़ैसलों में भागीदारी मिली है। पर **सिर्फ़ जाति पर ज़ोर देना नकारात्मक परिणाम दे सकता है**: यह **ग़रीबी, विकास और भ्रष्टाचार** जैसे ज़्यादा बड़े मुद्दों से लोगों का ध्यान भटका सकता है, और कुछ मामलों में जातिगत विभाजन **तनाव, टकराव और हिंसा** को भी जन्म देता है।",
  "**જ્ઞાતિગત અસમાનતાઓ:** લિંગ અને ધર્મથી વિપરીત, જ્ઞાતિ આધારિત વિભાજન ફક્ત ભારતમાં છે. બધા સમાજોમાં થોડી સામાજિક અસમાનતા અને શ્રમ વિભાજન હોય છે, પણ મોટા ભાગના સમાજોમાં વ્યવસાય એક પેઢીથી બીજી પેઢીમાં જતા નથી. જ્ઞાતિપ્રથા તેનું અતિશય સ્વરૂપ છે: તે **વંશપરંપરાગત વ્યવસાયિક વિભાજન** પર આધારિત છે જેને વિધિ-વિધાનોની માન્યતા મળેલી છે.\n"
  "- એક જ્ઞાતિના સભ્યો એક સામાજિક સમુદાય રચતા, જે એક જ કે મળતો વ્યવસાય કરતો, પોતાની જ્ઞાતિમાં જ લગ્ન કરતો અને બીજી જ્ઞાતિના લોકો સાથે ભોજન કરતો નહિ.\n"
  "- જ્ઞાતિપ્રથા 'અસ્પૃશ્ય' જૂથોના બહિષ્કાર અને તેમની સાથેના ભેદભાવ પર આધારિત હતી, જેમને **અસ્પૃશ્યતા**ની અમાનવીય પ્રથા સહન કરવી પડતી.\n"
  "- **જોતિબા ફુલે, ગાંધીજી, બી.આર. આંબેડકર અને પેરિયાર રામાસ્વામી નાયકર** જેવા રાજકીય નેતાઓ અને સમાજસુધારકોએ જ્ઞાતિગત અસમાનતા વિનાના સમાજ માટે કાર્ય કર્યું.\n\n"
  "**આધુનિક ભારતમાં ફેરફારો:** અંશતઃ તેમના પ્રયત્નોથી અને અંશતઃ બીજા સામાજિક-આર્થિક ફેરફારોથી જ્ઞાતિ અને જ્ઞાતિપ્રથામાં મોટા ફેરફારો થયા છે. **આર્થિક વિકાસ, મોટા પાયે શહેરીકરણ, સાક્ષરતા અને શિક્ષણનો વિકાસ, વ્યવસાયિક ગતિશીલતા** અને ગામડાંમાં જમીનદારોની સ્થિતિ નબળી પડવાથી જ્ઞાતિની જૂની ઊંચ-નીચની માન્યતાઓ તૂટી રહી છે. શહેરોમાં હવે એ વાતનું ખાસ મહત્ત્વ નથી કે રસ્તા પર આપણી સાથે કોણ ચાલે છે કે રેસ્ટોરાંમાં બાજુના ટેબલ પર કોણ જમે છે. **બંધારણે જ્ઞાતિ આધારિત કોઈ પણ ભેદભાવ પર પ્રતિબંધ** મૂક્યો અને જ્ઞાતિપ્રથાના અન્યાયને દૂર કરતી નીતિઓનો પાયો નાખ્યો.\n\n"
  "**પણ જ્ઞાતિ અદૃશ્ય થઈ નથી:**\n"
  "- હજી પણ મોટા ભાગના લોકો **પોતાની જ્ઞાતિ કે જનજાતિમાં જ લગ્ન** કરે છે.\n"
  "- બંધારણીય પ્રતિબંધ છતાં **અસ્પૃશ્યતા** સંપૂર્ણ નાબૂદ થઈ નથી.\n"
  "- સદીઓના લાભ અને ગેરલાભની અસરો આજે પણ અનુભવાય છે. જે જ્ઞાતિઓને જૂની પ્રથામાં શિક્ષણની પહોંચ હતી, તેમણે આધુનિક શિક્ષણમાં પણ સારો દેખાવ કર્યો; જેમને શિક્ષણથી વંચિત રખાયા, તેઓ પાછળ રહી ગયા. તેથી શહેરી મધ્યમવર્ગમાં **'ઉચ્ચ' જ્ઞાતિઓ**નું પ્રમાણ ઘણું વધારે છે. જ્ઞાતિ હજી પણ **આર્થિક દરજ્જા** સાથે ગાઢ રીતે જોડાયેલી છે.\n\n"
  "**રાજકારણમાં જ્ઞાતિ:** રાજકારણમાં જ્ઞાતિ અનેક સ્વરૂપે દેખાય છે:\n"
  "- ચૂંટણીમાં ઉમેદવાર પસંદ કરતી વખતે પક્ષો **મતદારોની જ્ઞાતિગત રચના** ધ્યાનમાં રાખે છે અને જીતવા માટે જરૂરી ટેકો મેળવવા જુદી જુદી જ્ઞાતિઓમાંથી ઉમેદવારો ઊભા રાખે છે.\n"
  "- રાજકીય પક્ષો અને ઉમેદવારો ટેકો મેળવવા **જ્ઞાતિગત લાગણીઓ**ને અપીલ કરે છે. કેટલાક પક્ષો અમુક જ્ઞાતિઓની તરફેણ કરનારા અને તેમના પ્રતિનિધિ તરીકે ઓળખાય છે.\n"
  "- **સાર્વત્રિક પુખ્ત મતાધિકાર** અને **એક વ્યક્તિ-એક મત**ના સિદ્ધાંતે નેતાઓને રાજકીય ટેકો મેળવવા લોકોને એકત્ર કરવા ફરજ પાડી. તેનાથી અત્યાર સુધી ઊતરતી ગણાતી જ્ઞાતિઓના લોકોમાં નવી જાગૃતિ આવી.\n\n"
  "**ફક્ત જ્ઞાતિથી ચૂંટણી નક્કી થતી નથી:**\n"
  "- દેશના **કોઈ પણ સંસદીય મતવિસ્તાર**માં કોઈ એક જ્ઞાતિની સ્પષ્ટ બહુમતી નથી. તેથી દરેક ઉમેદવાર અને પક્ષે એકથી વધુ જ્ઞાતિ અને સમુદાયનો વિશ્વાસ જીતવો પડે છે.\n"
  "- **કોઈ પક્ષને કોઈ જ્ઞાતિ કે સમુદાયના બધા મતદારોના મત મળતા નથી.** જ્યારે લોકો કોઈ જ્ઞાતિને કોઈ પક્ષની 'વોટ બૅન્ક' કહે, ત્યારે તેનો અર્થ સામાન્ય રીતે એ થાય કે તે જ્ઞાતિના મોટા ભાગના મતદારો તે પક્ષને મત આપે છે.\n"
  "- અનેક પક્ષો **એક જ જ્ઞાતિ**માંથી ઉમેદવારો ઊભા રાખી શકે, તેથી કેટલાક મતદારો પાસે પોતાની જ્ઞાતિના એકથી વધુ ઉમેદવારો હોય, જ્યારે ઘણા પાસે એક પણ ન હોય.\n"
  "- આપણા દેશમાં શાસક પક્ષ અને વર્તમાન સાંસદો-ધારાસભ્યો ઘણી વાર **ચૂંટણી હારે** છે. જો જ્ઞાતિઓ અને સમુદાયોની રાજકીય પસંદગીઓ સ્થિર હોત, તો આ શક્ય ન હોત.\n"
  "- મતદારોને રાજકીય પક્ષો સાથે મજબૂત લગાવ હોય છે, જે ઘણી વાર જ્ઞાતિના લગાવ કરતાં વધુ મજબૂત હોય છે. એક જ જ્ઞાતિ કે સમુદાયના લોકોનાં હિતો તેમની **આર્થિક સ્થિતિ** પ્રમાણે જુદાં હોય છે. એક જ જ્ઞાતિના ધનિક અને ગરીબ, કે સ્ત્રી અને પુરુષ ઘણી વાર જુદી રીતે મત આપે છે. **સરકારની કામગીરી** વિશે લોકોનું મૂલ્યાંકન અને **નેતાઓની લોકપ્રિયતા** પણ ચૂંટણીમાં નિર્ણાયક બને છે.\n\n"
  "**જ્ઞાતિમાં રાજકારણ:** રાજકારણ જ્ઞાતિગ્રસ્ત નથી બનતું; જ્ઞાતિ રાજકારણગ્રસ્ત બને છે:\n"
  "- દરેક જ્ઞાતિ પોતાને મોટી બનાવવા, અગાઉ બહાર રખાયેલી પડોશી જ્ઞાતિઓ કે પેટાજ્ઞાતિઓને પોતાનામાં સમાવવાનો પ્રયત્ન કરે છે.\n"
  "- જુદી જુદી જ્ઞાતિઓએ બીજી જ્ઞાતિઓ કે સમુદાયો સાથે **ગઠબંધન** કરવું પડે છે, અને આમ તેમની વચ્ચે સંવાદ અને વાટાઘાટ થાય છે.\n"
  "- રાજકારણમાં **'પછાત' અને 'આગળ પડતી'** જેવાં નવાં જ્ઞાતિ જૂથો ઊભાં થયાં છે.\n\n"
  "**અસરો:** જ્ઞાતિ રાજકારણથી **દલિતો અને અન્ય પછાત વર્ગો**ને નિર્ણય પ્રક્રિયામાં વધુ સારી પહોંચ મળી છે. પણ **ફક્ત જ્ઞાતિ પર ધ્યાન આપવાથી નકારાત્મક પરિણામો આવી શકે**: તે **ગરીબી, વિકાસ અને ભ્રષ્ટાચાર** જેવા વધુ મહત્ત્વના પ્રશ્નો પરથી ધ્યાન હટાવી શકે, અને કેટલાક કિસ્સામાં જ્ઞાતિગત વિભાજન **તણાવ, સંઘર્ષ અને હિંસા** તરફ દોરી જાય છે."),
 "s5.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s5.memory.body": (
  "- **महिलाओं के नुक़सान \"सा-नौ-म-बे-हिं\"**: साक्षरता, नौकरी, मज़दूरी, बेटे की चाह, हिंसा।\n- **महिलाओं के अंक \"54-76, 919, 1976\"**: साक्षरता 54% बनाम 76% (NCERT), बाल लिंग अनुपात 919, समान मज़दूरी अधिनियम 1976।\n"
  "- **सांप्रदायिकता के चार रूप \"वि-प्र-गो-हिं\"**: विश्वास, प्रभुत्व, गोलबंदी, हिंसा।\n"
  "- **धर्मनिरपेक्ष शासन \"कोई धर्म नहीं, आज़ादी, भेदभाव नहीं, समानता के लिए दख़ल\"** (छुआछूत पर रोक)।\n"
  "- **केवल जाति से चुनाव तय नहीं: \"बहुमत नहीं, पूरे वोट नहीं, एक जाति के प्रतिद्वंद्वी, सांसद हारते हैं\"।**\n- **जाति में राजनीति: \"बड़ा बनना, गठबंधन, पिछड़ा-अगड़ा\"।**",
  "- **સ્ત્રીઓના ગેરલાભ \"સા-નો-વે-દી-હિં\"**: સાક્ષરતા, નોકરી, વેતન, દીકરાની ઇચ્છા, હિંસા.\n- **સ્ત્રીઓના આંકડા \"54-76, 919, 1976\"**: સાક્ષરતા 54% સામે 76% (NCERT), બાળ જાતિ પ્રમાણ 919, સમાન વેતન ધારો 1976.\n"
  "- **કોમવાદનાં ચાર સ્વરૂપ \"મા-વ-એ-હિં\"**: માન્યતાઓ, વર્ચસ્વ, એકત્રીકરણ, હિંસા.\n"
  "- **બિનસાંપ્રદાયિક રાજ્ય \"કોઈ ધર્મ નહિ, સ્વતંત્રતા, ભેદભાવ નહિ, સમાનતા માટે દખલ\"** (અસ્પૃશ્યતા પર પ્રતિબંધ).\n"
  "- **ફક્ત જ્ઞાતિથી ચૂંટણી નક્કી નથી: \"બહુમતી નહિ, બધા મત નહિ, એક જ્ઞાતિના હરીફો, સાંસદો હારે\".**\n- **જ્ઞાતિમાં રાજકારણ: \"મોટા થવું, ગઠબંધન, પછાત-આગળ પડતી\".**"),
 "s5.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s5.mistakes.body": (
  "1. लैंगिक विभाजन को जैविक बताना: यह **सामाजिक अपेक्षाओं और रूढ़ छवियों** पर आधारित है।\n2. यह सोचना कि केवल महिलाएँ नारीवादी हो सकती हैं: नारीवादी **महिला या पुरुष** कोई भी हो सकता है जो समान अधिकारों में विश्वास करे।\n"
  "3. धर्म और राजनीति के हर संबंध को सांप्रदायिक कहना: गांधीजी के नैतिक मूल्य, अल्पसंख्यकों की सुरक्षा और पारिवारिक क़ानूनों में सुधार सांप्रदायिक **नहीं** हैं।\n"
  "4. यह कहना कि धर्मनिरपेक्ष शासन का धर्म से कोई लेना-देना नहीं: वह समानता के लिए **दख़ल** दे सकता है, जैसे छुआछूत पर रोक।\n"
  "5. यह कहना कि केवल जाति चुनाव तय करती है: किसी चुनाव क्षेत्र में एक जाति का बहुमत नहीं, और सांसद अक्सर हारते हैं।\n"
  "6. लिखना कि लोकसभा में महिलाओं के लिए एक-तिहाई आरक्षण लागू है: 2023 का अधिनियम अगली जनगणना और परिसीमन के बाद लागू होगा; अभी यह **पंचायतों और नगरपालिकाओं** में लागू है।",
  "1. લૈંગિક વિભાજનને જૈવિક ગણવું: તે **સામાજિક અપેક્ષાઓ અને રૂઢ માન્યતાઓ** પર આધારિત છે.\n2. માનવું કે ફક્ત સ્ત્રીઓ જ નારીવાદી હોઈ શકે: નારીવાદી **સ્ત્રી કે પુરુષ** કોઈ પણ હોઈ શકે જે સમાન અધિકારોમાં માને.\n"
  "3. ધર્મ અને રાજકારણના દરેક સંબંધને કોમવાદી ગણવો: ગાંધીજીનાં નૈતિક મૂલ્યો, લઘુમતીઓનું રક્ષણ અને કૌટુંબિક કાયદામાં સુધારો કોમવાદી **નથી**.\n"
  "4. કહેવું કે બિનસાંપ્રદાયિક રાજ્યને ધર્મ સાથે કોઈ લેવાદેવા નથી: તે સમાનતા માટે **દખલ** કરી શકે, જેમ કે અસ્પૃશ્યતા પર પ્રતિબંધ.\n"
  "5. કહેવું કે ફક્ત જ્ઞાતિ ચૂંટણી નક્કી કરે છે: કોઈ મતવિસ્તારમાં એક જ્ઞાતિની બહુમતી નથી, અને સાંસદો ઘણી વાર હારે છે.\n"
  "6. લખવું કે લોકસભામાં સ્ત્રીઓ માટે એક-તૃતીયાંશ અનામત લાગુ છે: 2023નો અધિનિયમ આગામી વસ્તી ગણતરી અને સીમાંકન પછી લાગુ થશે; હાલ તે **પંચાયતો અને નગરપાલિકાઓમાં** લાગુ છે."),
 "s5.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s5.tip.body": (
  "छात्रों से एक हफ़्ते तक नोट करवाइए कि घर का हर काम कौन करता है (खाना बनाना, सफ़ाई, ख़रीदारी, बिल भरना, होमवर्क में मदद)। नतीजों को बिना नाम के इकट्ठा कीजिए और चर्चा कीजिए: क्या ये भूमिकाएँ जीव-विज्ञान पर आधारित हैं या सामाजिक अपेक्षाओं पर?",
  "વિદ્યાર્થીઓને એક અઠવાડિયા સુધી નોંધવા કહો કે ઘરનું દરેક કામ કોણ કરે છે (રસોઈ, સફાઈ, ખરીદી, બિલ ભરવાં, હોમવર્કમાં મદદ). પરિણામો નામ વગર ભેગાં કરો અને ચર્ચા કરો: શું આ ભૂમિકાઓ જીવવિજ્ઞાન પર આધારિત છે કે સામાજિક અપેક્ષાઓ પર?"),
 "s5.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s5.reflection.body": (
  "कोई चुनावी विज्ञापन या भाषण याद कीजिए जो आपने देखा हो। क्या उसमें लिंग, धर्म या जाति के नाम पर अपील थी? क्या वह अपील बराबरी के लिए थी (स्वस्थ) या किसी दूसरे समूह के ख़िलाफ़ (अस्वस्थ)?",
  "તમે જોયેલી કોઈ ચૂંટણી જાહેરખબર કે ભાષણ યાદ કરો. શું તેમાં લિંગ, ધર્મ કે જ્ઞાતિના નામે અપીલ હતી? શું તે અપીલ સમાનતા માટે હતી (તંદુરસ્ત) કે બીજા જૂથની વિરુદ્ધ (અતંદુરસ્ત)?"),
 "s5.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s5.connection.body": (
  "- **अध्याय 1 (सत्ता की साझेदारी):** सामाजिक समूहों के साथ सत्ता की साझेदारी।\n- **अध्याय 4 (राजनीतिक दल):** दल मतदाताओं को कैसे गोलबंद करते हैं।\n"
  "- **अध्याय 5 (लोकतंत्र के परिणाम):** नागरिकों, ख़ासकर महिलाओं और वंचित जातियों की गरिमा और आज़ादी।",
  "- **પ્રકરણ 1 (સત્તાની ભાગીદારી):** સામાજિક જૂથો સાથે સત્તાની ભાગીદારી.\n- **પ્રકરણ 4 (રાજકીય પક્ષો):** પક્ષો મતદારોને કેવી રીતે એકત્ર કરે છે.\n"
  "- **પ્રકરણ 5 (લોકશાહીનાં પરિણામો):** નાગરિકો, ખાસ કરીને સ્ત્રીઓ અને વંચિત જ્ઞાતિઓનું ગૌરવ અને સ્વતંત્રતા."),
 "s5.mastery.title": ("महारत चुनौती", "નિપુણતા પડકાર"),
 "s5.mastery.body": (
  "'भारत में केवल जाति चुनाव परिणाम तय नहीं कर सकती।' लगभग 120 शब्दों में पुष्टि कीजिए।\n\n"
  "**आदर्श उत्तर:** राजनीति में जाति की भूमिका है: पार्टियाँ मतदाताओं की जातियों को ध्यान में रखकर उम्मीदवार चुनती हैं और जातिगत भावनाओं को उकसाती हैं। पर केवल जाति परिणाम तय नहीं कर सकती। "
  "किसी भी संसदीय चुनाव क्षेत्र में एक जाति का स्पष्ट बहुमत नहीं है, इसलिए हर उम्मीदवार को कई जातियों और समुदायों का समर्थन जीतना पड़ता है। किसी पार्टी को किसी जाति के सभी वोट नहीं मिलते। "
  "कई पार्टियाँ एक ही जाति से उम्मीदवार उतारती हैं, इसलिए उस जाति के मतदाताओं को उनमें से चुनना पड़ता है। सत्तारूढ़ दल और वर्तमान सांसद-विधायक अक्सर हारते हैं, जो जातिगत पसंद तय होने पर संभव न होता। "
  "मतदाता सरकार के कामकाज और नेताओं की लोकप्रियता को भी परखते हैं, और एक जाति के अमीर और ग़रीब अक्सर अलग-अलग वोट देते हैं।",
  "'ભારતમાં ફક્ત જ્ઞાતિ ચૂંટણીનાં પરિણામો નક્કી કરી શકે નહિ.' આશરે 120 શબ્દોમાં સમર્થન કરો.\n\n"
  "**આદર્શ જવાબ:** રાજકારણમાં જ્ઞાતિની ભૂમિકા છે: પક્ષો મતદારોની જ્ઞાતિગત રચના ધ્યાનમાં રાખી ઉમેદવારો પસંદ કરે છે અને જ્ઞાતિગત લાગણીઓને અપીલ કરે છે. પણ ફક્ત જ્ઞાતિ પરિણામ નક્કી કરી શકે નહિ. "
  "કોઈ પણ સંસદીય મતવિસ્તારમાં એક જ્ઞાતિની સ્પષ્ટ બહુમતી નથી, તેથી દરેક ઉમેદવારે અનેક જ્ઞાતિઓ અને સમુદાયોનો ટેકો જીતવો પડે છે. કોઈ પક્ષને કોઈ જ્ઞાતિના બધા મત મળતા નથી. "
  "અનેક પક્ષો એક જ જ્ઞાતિમાંથી ઉમેદવારો ઊભા રાખે છે, તેથી તે જ્ઞાતિના મતદારોએ તેમાંથી પસંદગી કરવી પડે છે. શાસક પક્ષો અને વર્તમાન સાંસદો-ધારાસભ્યો ઘણી વાર હારે છે, જે જ્ઞાતિગત પસંદગી સ્થિર હોત તો શક્ય ન હોત. "
  "મતદારો સરકારની કામગીરી અને નેતાઓની લોકપ્રિયતા પણ જુએ છે, અને એક જ જ્ઞાતિના ધનિક અને ગરીબ ઘણી વાર જુદી રીતે મત આપે છે."),
 "s5.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s5.summary.body": (
  "- लैंगिक विभाजन सामाजिक अपेक्षाओं पर आधारित है, जीव-विज्ञान पर नहीं; श्रम का लैंगिक विभाजन महिलाओं के काम को मान्यता नहीं देता।\n"
  "- नारीवादी आंदोलनों ने वोट के अधिकार और बराबरी की माँग की; भारत अब भी पितृप्रधान है: कम साक्षरता, कम वेतन, बेटे की चाह और हिंसा।\n"
  "- 2019 में लोकसभा में महिलाएँ लगभग 14% थीं; स्थानीय निकायों में एक-तिहाई सीटें आरक्षित हैं; 2023 का अधिनियम लोकसभा और विधानसभाओं में एक-तिहाई आरक्षित करेगा।\n"
  "- सांप्रदायिकता धर्म को राष्ट्र का आधार मानती है; इसके रूप हैं रोज़मर्रा के विश्वास, प्रभुत्व की चाह, धार्मिक गोलबंदी और हिंसा।\n"
  "- भारत धर्मनिरपेक्ष है: कोई आधिकारिक धर्म नहीं, धर्म की आज़ादी, भेदभाव नहीं, और समानता के लिए शासन का दख़ल।\n"
  "- जाति अब भी मायने रखती है, पर केवल जाति से चुनाव तय नहीं होते; राजनीति ने भी जाति को बदला है, और सिर्फ़ जाति पर ज़ोर हानिकारक हो सकता है।",
  "- લૈંગિક વિભાજન સામાજિક અપેક્ષાઓ પર આધારિત છે, જીવવિજ્ઞાન પર નહિ; શ્રમનું લૈંગિક વિભાજન સ્ત્રીઓના કામને માન્યતા આપતું નથી.\n"
  "- નારીવાદી આંદોલનોએ મતાધિકાર અને સમાનતાની માગણી કરી; ભારત હજી પિતૃસત્તાક છે: ઓછી સાક્ષરતા, ઓછું વેતન, દીકરાની ઇચ્છા અને હિંસા.\n"
  "- 2019માં લોકસભામાં સ્ત્રીઓ આશરે 14% હતી; સ્થાનિક સંસ્થાઓમાં એક-તૃતીયાંશ બેઠકો અનામત છે; 2023નો અધિનિયમ લોકસભા અને વિધાનસભાઓમાં એક-તૃતીયાંશ અનામત રાખશે.\n"
  "- કોમવાદ ધર્મને રાષ્ટ્રનો આધાર માને છે; તેનાં સ્વરૂપો છે રોજિંદી માન્યતાઓ, વર્ચસ્વની ઇચ્છા, ધાર્મિક એકત્રીકરણ અને હિંસા.\n"
  "- ભારત બિનસાંપ્રદાયિક છે: કોઈ સત્તાવાર ધર્મ નહિ, ધાર્મિક સ્વતંત્રતા, ભેદભાવ નહિ, અને સમાનતા માટે રાજ્યની દખલ.\n"
  "- જ્ઞાતિ હજી મહત્ત્વની છે, પણ ફક્ત જ્ઞાતિથી ચૂંટણી નક્કી થતી નથી; રાજકારણે પણ જ્ઞાતિને બદલી છે, અને ફક્ત જ્ઞાતિ પર ધ્યાન હાનિકારક બની શકે."),
 "s5.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટેની ટિપ્સ"),
 "s5.examtips.body": (
  "- 2025-26 के प्रतिदर्श प्रश्न-पत्र में अभिकथन-कारण प्रश्न था: सिर्फ़ जाति पर ज़ोर देना लोकतंत्र में नकारात्मक परिणाम दे सकता है (उत्तर: दोनों सही, R, A की व्याख्या करता है), और 2 अंक का प्रश्न: जीवन के दो पहलू जहाँ महिलाएँ असमानता झेलती हैं (शिक्षा, नौकरी, वेतन, बेटे की चाह, हिंसा)।\n"
  "- 3/5 अंक के पसंदीदा प्रश्न: सांप्रदायिकता के रूप, धर्मनिरपेक्ष शासन की विशेषताएँ, आज की जातिगत असमानताएँ, केवल जाति से चुनाव क्यों तय नहीं होते, महिलाओं का प्रतिनिधित्व।\n"
  "- हर बिंदु में एक तथ्य या उदाहरण लिखें (54% साक्षरता, समान मज़दूरी अधिनियम 1976, बाल लिंग अनुपात 919)।",
  "- 2025-26ના નમૂનાના પ્રશ્નપત્રમાં વિધાન-કારણ પ્રશ્ન હતો: ફક્ત જ્ઞાતિ પર ધ્યાન આપવાથી લોકશાહીમાં નકારાત્મક પરિણામો આવી શકે (જવાબ: બંને સાચાં, R એ A ની સમજૂતી આપે છે), અને 2 ગુણનો પ્રશ્ન: જીવનનાં બે પાસાં જ્યાં સ્ત્રીઓ અસમાનતા સહન કરે છે (શિક્ષણ, નોકરી, વેતન, દીકરાની ઇચ્છા, હિંસા).\n"
  "- 3/5 ગુણના પ્રિય પ્રશ્નો: કોમવાદનાં સ્વરૂપો, બિનસાંપ્રદાયિક રાજ્યનાં લક્ષણો, આજની જ્ઞાતિગત અસમાનતાઓ, ફક્ત જ્ઞાતિથી ચૂંટણી કેમ નક્કી થતી નથી, સ્ત્રીઓનું પ્રતિનિધિત્વ.\n"
  "- દરેક મુદ્દામાં એક તથ્ય કે ઉદાહરણ લખો (54% સાક્ષરતા, સમાન વેતન ધારો 1976, બાળ જાતિ પ્રમાણ 919)."),
 "s5.flash1.front": ("पितृसत्ता क्या है?", "પિતૃસત્તા શું છે?"),
 "s5.flash1.back": ("शाब्दिक अर्थ पिता का शासन; ऐसी व्यवस्था जो पुरुषों को अधिक महत्त्व और महिलाओं पर अधिक शक्ति देती है।", "શાબ્દિક અર્થ પિતાનું શાસન; એવી વ્યવસ્થા જે પુરુષોને વધુ મહત્ત્વ અને સ્ત્રીઓ પર વધુ સત્તા આપે છે."),
 "s5.flash2.front": ("सांप्रदायिकता क्या है?", "કોમવાદ શું છે?"),
 "s5.flash2.back": ("इस विश्वास पर आधारित राजनीति कि धर्म ही सामाजिक समुदाय का मुख्य आधार है, और जो धर्म का इस्तेमाल विशिष्टता और पक्षपात के लिए करती है।", "એવી માન્યતા પર આધારિત રાજકારણ કે ધર્મ જ સામાજિક સમુદાયનો મુખ્ય આધાર છે, અને જે ધર્મનો ઉપયોગ અલગતા અને પક્ષપાત માટે કરે છે."),
 "s5.flash3.front": ("भारत के धर्मनिरपेक्ष शासन की चार विशेषताएँ बताइए।", "ભારતના બિનસાંપ્રદાયિક રાજ્યનાં ચાર લક્ષણો જણાવો."),
 "s5.flash3.back": ("कोई आधिकारिक धर्म नहीं; किसी भी धर्म को मानने, अभ्यास और प्रचार की आज़ादी; धर्म के आधार पर भेदभाव नहीं; धर्मों के अंदर समानता के लिए शासन का दख़ल।", "કોઈ સત્તાવાર ધર્મ નહિ; કોઈ પણ ધર્મ પાળવા, આચરવા અને પ્રચાર કરવાની સ્વતંત્રતા; ધર્મના આધારે ભેદભાવ નહિ; ધર્મોમાં સમાનતા માટે રાજ્યની દખલ."),
 "s5.flash4.front": ("श्रम का लैंगिक विभाजन क्या है?", "શ્રમનું લૈંગિક વિભાજન શું છે?"),
 "s5.flash4.back": ("ऐसी व्यवस्था जिसमें घर के अंदर का सारा काम औरतें करती हैं या घरेलू नौकरों से कराती हैं।", "એવી વ્યવસ્થા જેમાં ઘરની અંદરનું બધું કામ સ્ત્રીઓ કરે છે અથવા ઘરનોકરો પાસે કરાવે છે."),
}
